insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-1','Алкоголь','🥃 Херес, Джин, Вермут','--- Херес Что это: Креплёное вино из испанской Андалусии. Как делается: Система "Солера" — молодое вино смешивают с выдержанным. • Фино — сухой, лёгкий, свежий. • Элегант…','published',10,false,'🥃 Херес, Джин, Вермут Алкоголь --- Херес Что это: Креплёное вино из испанской Андалусии. Как делается: Система "Солера" — молодое вино смешивают с выдержанным. • Фино — сухой, лёгкий, свежий. • Элегант… Херес Что это: Креплёное вино из испанской Андалусии. Как делается: Система "Солера" — молодое вино смешивают с выдержанным. Фино — сухой, лёгкий, свежий. Элеганте — сладкий, кремовый, карамельный. Как пить: Фино - быстро, большими глотками, как освежающее белое вино (узкая коньячная рюмка). Элеганте Крим - Медленно, смакуя маленькими глотками в качестве дижестива (узкая коньячная рюмка). Факт: Сладкий стиль хереса Cream появился не в Испании, а благодаря капризам британской аристократии 19 века, которая обожала испанские вина, но считала их слишком сухими. Джин Что это: Крепкий алкогольный напиток с доминирующим ароматом можжевельника. Как делается: Дистилляция (отделение чистого спирта от воды с помощью нагревания) зернового спирта с ботаникалами (цитрусы, кориандр, кардамон, травы). Подача: в коктейлях; чистый — в роксе со льдом или без. Факт: изначально использовался как можжевеловое средство, а не напиток. Вермут Что это: креплёное вино с травами и специями. Подвиды: Bianco — светлый, мягко-сладкий. Rosso — красный, пряный. Extra Dry — сухой. Подача: охлаждённым, чистым или со льдом. Факт: название от нем. Wermut («полынь») — исторически главный ингредиент.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
