insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-2','Алкоголь','🥃 Ром, Водка, Виски, Бурбон','--- Ром Что это: Ром — это крепкий алкоголь, который делают из сахарного тростника (тростниковой мелассы/патоки или чистого тростникового сока). --- Ром белый (Havana Clu…','published',20,false,'🥃 Ром, Водка, Виски, Бурбон Алкоголь --- Ром Что это: Ром — это крепкий алкоголь, который делают из сахарного тростника (тростниковой мелассы/патоки или чистого тростникового сока). --- Ром белый (Havana Clu… Ром Что это: Ром — это крепкий алкоголь, который делают из сахарного тростника (тростниковой мелассы/патоки или чистого тростникового сока). Ром белый (Havana Club 3 años) Что это: Прозрачный, легкий ром с мягким вкусом. Его выдерживают недолго (или не выдерживают вовсе) и часто фильтруют для удаления цвета. Подача: охлаждённым, шотами или в коктейлях. Факт: Ром называют напитком пиратов и моряков не просто так. В 17-18 веках на кораблях британского флота пресная вода в бочках быстро протухала и зеленела. Чтобы обеззаразить воду, в неё начали добавлять ром. Позже морякам Британского королевского флота стали официально выдавать ежедневную порцию рома (эта традиция продержалась аж до 1970 года!). Ром тёмный (Plantation Original Dark, Legendario Elixir de Cuba 7) Что это: Густой, ароматный ром с глубоким вкусом специй, карамели и патоки. Его долго выдерживают в сильно обожженных дубовых бочках. Подача: чистым в роксе со льдом или без. Факт: На Карибах очень жарко, поэтому ром в бочках созревает в три раза быстрее, чем виски в Шотландии. Так что этот напиток по вкусу такой же плотный и насыщенный, как дорогой 15-летний виски. Водка Что это: Максимально чистый и крепкий алкоголь, который получают путем смешивания ректификованного (максимально чистый, медицинский спирт крепостью 96%, в котором нет ничего, кроме самого алкоголя) спирта и умягченной воды. Сырьё: Ее делают из зерна (в основном люкс-класса из пшеницы или ржи), реже — из картофеля. Зерно дает напитку ту самую классическую хлебную мягкость. Классификация спиртов: «Люкс»: Классический качественный спирт, делается из смеси зерна и картофеля. «Альфа»: Премиальный стандарт, изготавливается строго из 100% зерна (пшеницы или ржи). Поэтому такая водка пьется значительно мягче и реже дает похмелье. Виски Что это: Крепкий алкогольный напиток из зерна, который обязательно выдерживают в дубовых бочках Подвиды: Односолодовый (Single Malt): Делается строго из ячменного солода. Виски с одной винокурни. Купажированный (Blended Whisky) — это смесь двух типов виски: яркого солодового и мягкого зернового. Подача: чистым, со льдом или с водой — по желанию гостя. Факт: Виски появилось в Ирландии и Шотландии около 15 века. "Whisky" от гэльского "uisce beatha" — «вода жизни». Цифра на бутылке — возраст самого молодого виски в купаже. Бурбон Что это: это американский виски, который делают преимущественно из кукурузы. Главное отличие бурбона от обычного виски заключается в сырье и новых бочках. В то время как классический виски делают из ячменя и выдерживают в старых бочках, бурбон производят из сладкой кукурузы и созревает он исключительно в свежих, сильно обожженных изнутри дубовых бочках. Подача: чистым, со льдом или с водой — по желанию гостя. Факт: Американские производители бурбона имеют право использовать свои дубовые бочки всего один раз в жизни. Сразу после слива напитка эти дефицитные бочки массово скупают шотландцы, чтобы годами выдерживать в них свой знаменитый шотландский виски.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
