insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-3','Алкоголь','🥃 Коньяк, Бренди, Кальвадос','--- Коньяк Что это: Крепкий алкогольный напиток, который делают из винограда и выдерживают в дубовых бочках. Строго из региона Коньяк (Франция). Возраст коньяка по этикет…','published',30,false,'🥃 Коньяк, Бренди, Кальвадос Алкоголь --- Коньяк Что это: Крепкий алкогольный напиток, который делают из винограда и выдерживают в дубовых бочках. Строго из региона Коньяк (Франция). Возраст коньяка по этикет… Коньяк Что это: Крепкий алкогольный напиток, который делают из винограда и выдерживают в дубовых бочках. Строго из региона Коньяк (Франция). Возраст коньяка по этикетке: V.S. (Very Special): Выдержка от 2 лет. Дерзкий, фруктовый и легкий коньяк. V.S.O.P. (Very Superior Old Pale): Выдержка от 4 лет. Мягкий, с заметными древесными и ванильными нотами. X.O. (Extra Old): Выдерживается минимум 10 лет. Это очень сложный напиток с ароматом сигарного табака, кожи и темного шоколада. Подача: комнатной температуры, в снифтере (бокал-тюльпан), можно слегка согреть ладонями. Факт: название юридически и географически защищено — бренди из других стран коньяком не называют. Бренди Что это: Крепкий алкогольный напиток, который делают из винограда или любого фруктового, ягодного сока. Арарат 3 года Что это: армянский виноградный бренди. Как делается: выдержка в дубовых бочках даёт ванильные, фруктовые и древесные оттенки. Подача: комнатной температуры, в бокале "Снифтер". Исторический Факт: Во время Ялтинской конференции в 1945 году Сталин угостил Уинстона Черчилля армянским коньяком "Двин". Британский премьер настолько влюбился в его вкус, что Сталин пообещал присылать ему по 400 бутылок каждый год.Черчилль пил его ежедневно. Но спустя время он сердито написал Сталину, что коньяк испортился — у него пропал тот самый фирменный аромат дуба и сухофруктов.Оказалось, что главного купажиста завода, легендарного Маркара Седракяна, за политические взгляды сослали в Сибирь, и технологию без него нарушили. Сталин тут же приказал вернуть мастера из лагерей, полностью восстановить в правах и вернуть на завод. Седракян исправил рецептуру, Черчилль снова получил свой идеальный напиток, а Армения сохранила своего главного гения купажа. Кальвадос Что это: яблочный (или грушевый) бренди из Нормандии (Франция). Как делается: двойная перегонка яблочного сидра, выдержка в дубовых бочках. Вкус — яблоки, груши, ваниль, древесина, специи. Подача: комнатной температуры, в снифтере или тюльпане, как дижестив (после еды). Факт: кальвадос — один из немногих фруктовых бренди с защищённым наименованием по происхождению (AOC).',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
