insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-3_block_11','lesson-3',100,'paragraph','Исторический Факт: Во время Ялтинской конференции в 1945 году Сталин угостил Уинстона Черчилля армянским коньяком "Двин". Британский премьер настолько влюбился в его вкус, что Сталин пообещал присылать ему по 400 бутылок каждый год.Черчилль пил его ежедневно. Но спустя время он сердито написал Сталину, что коньяк испортился — у него пропал тот самый фирменный аромат дуба и сухофруктов.Оказалось, что главного купажиста завода, легендарного Маркара Седракяна, за политические взгляды сослали в Сибирь, и технологию без него нарушили. Сталин тут же приказал вернуть мастера из лагерей, полностью восстановить в правах и вернуть на завод. Седракян исправил рецептуру, Черчилль снова получил свой идеальный напиток, а Армения сохранила своего главного гения купажа.','[{"type":"bold","from":0,"to":764}]'::jsonb,null,null,null,null,null,'','','');
