insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-4','Алкоголь','🍸 Ликёры','Что это: это сладкий алкогольный напиток, который делают на основе крепкого спирта с добавлением фруктов, ягод, трав, специй или сливок. --- Апероль Что это: итальянский…','published',40,false,'🍸 Ликёры Алкоголь Что это: это сладкий алкогольный напиток, который делают на основе крепкого спирта с добавлением фруктов, ягод, трав, специй или сливок. --- Апероль Что это: итальянский… Что это: это сладкий алкогольный напиток, который делают на основе крепкого спирта с добавлением фруктов, ягод, трав, специй или сливок. Апероль Что это: итальянский алкогольный напиток (аперитив) ярко-оранжевого цвета, горьковато-сладкий, цитрусовый. Чем отличается от Кампари: мягче и слаще. Подача: основа Aperol Spritz, чистый — со льдом и содой. Факт: появился в 1919 году, но стал мировым хитом благодаря Spritz. Кампари Что это: горький итальянский алкогольный напиток (аперитив) ярко-красного цвета. Чем отличается от Апероля: более горький, насыщенный, терпкий. Подача: в коктейлях (Негрони, Бульвардье) или чистым со льдом. Факт: точный рецепт — коммерческая тайна до сих пор. Трипл-сек Что это: прозрачный сладкий апельсиновый ликёр. Подача: в коктейлях или чистым как дижестив. Факт: название от «тройная сухость», но уровень сладости у разных брендов отличается. Бейлис Что это: сливочный ликёр на основе ирландского виски, сливок. Вкус — шоколад, кофе, сливки. Подача: чистым со льдом, в коктейлях, с кофе. Факт: один из первых массовых сливочных ликёров, появился в 1970-х. Бехеровка Что это: чешский травяный ликёр, горьковато-сладкий, пряный. Подача: охлаждённой, часто как дижестив. Факт: создавалась как лечебные капли, а не алкоголь. Jägermeister (Ягермейстер) Что это: немецкий травяной ликёр из десятков трав, кореньев, фруктов и специй. Насыщенный, горько-сладкий. Подача: сильно охлаждённым, шотами. Факт: название — «главный егерь», отсюда олень с крестом на этикетке.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
