insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-5','Алкоголь','🌵 Текила','Что это: Крепкий мексиканский алкогольный напиток, который делают строго из сока голубой агавы. --- Текила Blanco Что это: молодая текила без выдержки в дубе или с очень…','published',50,false,'🌵 Текила Алкоголь Что это: Крепкий мексиканский алкогольный напиток, который делают строго из сока голубой агавы. --- Текила Blanco Что это: молодая текила без выдержки в дубе или с очень… Что это: Крепкий мексиканский алкогольный напиток, который делают строго из сока голубой агавы. Текила Blanco Что это: молодая текила без выдержки в дубе или с очень короткой. Сохраняет яркий вкус голубой агавы — травянистый, перечный, цитрусовый. Подача: чистым в шотах или в коктейлях. Факт: производится только из строго определённого вида голубой агавы. Текила Reposado / Gold Что это: «отдохнувшая» текила. Reposado: выдержка 2–12 месяцев в дубе, появляются ноты ванили, карамели, дерева. Gold: золотой цвет может быть от добавок или купажа, а не от выдержки. Подача: чистым в шотах или в коктейлях. Факт: Reposado переводится как «отдохнувшая» — текила отдыхает в бочке перед розливом.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
