insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-6','Пиво','Как появилось пиво','Пиво — один из старейших напитков человечества, первые упоминания найдены в Древнем Шумере более 5000 лет назад.','published',60,false,'Как появилось пиво Пиво Пиво — один из старейших напитков человечества, первые упоминания найдены в Древнем Шумере более 5000 лет назад. Пиво — один из старейших напитков человечества, первые упоминания найдены в Древнем Шумере более 5000 лет назад.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
