insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-8','Вино','Различие между "Шампанским" и "Игристым" вином','Главное различие между "Шампанским" и "Игристым" вином заключается в их происхождении и способе производства. Шампанское - производится исключительно в регионе Шампань на…','published',80,false,'Различие между "Шампанским" и "Игристым" вином Вино Главное различие между "Шампанским" и "Игристым" вином заключается в их происхождении и способе производства. Шампанское - производится исключительно в регионе Шампань на… Главное различие между "Шампанским" и "Игристым" вином заключается в их происхождении и способе производства. Шампанское - производится исключительно в регионе Шампань на северо-востоке Франции. Производство строго регулируется французским законодательством, начиная от сорта винограда и метода ферментации до минимального срока выдержки. Игристое – это вино, насыщенное углекислым газом в результате природного брожения. Так происходит, когда дрожжи поглощают виноградный сок, выделяя спирт и углекислый газ.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-8_block_1','lesson-8',0,'paragraph','Главное различие между "Шампанским" и "Игристым" вином заключается в их происхождении и способе производства. Шампанское - производится исключительно в регионе Шампань на северо-востоке Франции. Производство строго регулируется французским законодательством, начиная от сорта винограда и метода ферментации до минимального срока выдержки.
