insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-9','Вино','Виды и классификация Игристого вина:','Виды Игристого: Шампанское: Главное игристое из французской Шампани из сортов винограда Шардоне, Пино Нуар и Пино Менье. Просекко: Свежее итальянское вино из винограда Гл…','published',90,false,'Виды и классификация Игристого вина: Вино Виды Игристого: Шампанское: Главное игристое из французской Шампани из сортов винограда Шардоне, Пино Нуар и Пино Менье. Просекко: Свежее итальянское вино из винограда Гл… Виды Игристого: Шампанское: Главное игристое из французской Шампани из сортов винограда Шардоне, Пино Нуар и Пино Менье. Просекко: Свежее итальянское вино из винограда Глера, производимое резервуарным методом (Шарма) с ярко выраженными фруктово-цветочными нотками. Кава: Испанский ответ Шампани, более доступный, но сделанный по той же технологии, но из местных сортов винограда Макабео, Ксарелло и Парельяда. Креман: Французское игристое вино, производимое по классической технологии за пределами региона Шампань (в Бургундии, Эльзасе и др.). Асти: Сладкое, ароматное мускатное вино из Пьемонта на основе винограда Москато (Мускат). Ламбруско: Итальянское вино (бывает красным, розовым, белым), чаще всего полусухое или полусладкое. Пет-нат: Натуральное, часто мутноватое игристое с мягким газом, яркой фруктовостью и пивной пробкой. Может производиться в любой стране и из любых сортов винограда. Зект: Традиционное игристое вино из Германии и Австрии, чаще всего производимое из сорта винограда Рислинг. Классификация игристого по уровню сахара: Brut Nature: Самое сухое вино без добавления сахара. Extra Brut: Очень сухое игристое. Brut (Брют): Самый популярный сухой тип с минимальным количеством сахара. Extra Dry: Вино чуть слаще брюта. Demi-Sec (Полусухое / Полусладкое) и Sweet (Сладкое): Десертные варианты с высоким содержанием сахара.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
