insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-10','Вино','Шампанское "BeerBistro"','- Deutz Classic Brut - страна: Франция, крепость: 12%, виноград: пино нуар, шардоне, пино менье. Вкус: Вкус шампанского объединяет свежесть и маслянистость и завершается…','published',100,false,'Шампанское "BeerBistro" Вино - Deutz Classic Brut - страна: Франция, крепость: 12%, виноград: пино нуар, шардоне, пино менье. Вкус: Вкус шампанского объединяет свежесть и маслянистость и завершается… Deutz Classic Brut - страна: Франция, крепость: 12%, виноград: пино нуар, шардоне, пино менье. Вкус: Вкус шампанского объединяет свежесть и маслянистость и завершается длительным фруктовым послевкусием. Аромат: В экспрессивном аромате шампанского сначала раскрываются ноты белых цветов и боярышника, затем тона поджаренного хлеба, миндальной пасты и зрелых фруктов — груши и яблока. Сочетание: Шампанское подходит как аперитив, а также прекрасный аккомпанемент к морским блюдам, равно как к антре из цыпленка. Температура подачи: 8-10 °C Michel Forget Rose Premier Cru Brut – страна: Франция, тип: розовое, крепость: 12%, виноград: пино нуар, пино менье, шардоне. Вкус: Интенсивный вкус шампанского обладает прекрасным балансом, мелкозернистой текстурой, нежной кислотностью. В его палитре сфокусированы оттенки спелой сливы, земляники, дыни и минералов. Прекрасный пример гармоничного сочетания округлости и свежести вкуса. Аромат: Исключительной свежести аромат шампанского представлен широким спектром оттенков: шелковицы, малины, красной смородины, земляники и дыни. Нюансы миндаля и минералов добавляют ему приятную сложность. Сочетания: Вино подается с разнообразными ягодными и фруктовыми десертами, свежими ягодами и фруктами, салатами. Также сочетается с перепелами, фуа-гра, мясом под клюквенным соусом. Температура подачи: 10–12 °С',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
