insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-10_block_5','lesson-10',40,'paragraph','Вкус: Интенсивный вкус шампанского обладает прекрасным балансом, мелкозернистой текстурой, нежной кислотностью. В его палитре сфокусированы оттенки спелой сливы, земляники, дыни и минералов. Прекрасный пример гармоничного сочетания округлости и свежести вкуса.
