insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-11','Вино','Игристое вино "BeerBistro"','- Абрау Дюрсо - белое игристое; страна: Россия, Краснодарский край. типы в меню: Брют, Полусухое, Полусладкое; крепость: 12,5% • Брют - минимальное количество сахара (до…','published',110,false,'Игристое вино "BeerBistro" Вино - Абрау Дюрсо - белое игристое; страна: Россия, Краснодарский край. типы в меню: Брют, Полусухое, Полусладкое; крепость: 12,5% • Брют - минимальное количество сахара (до… Абрау Дюрсо - белое игристое; страна: Россия, Краснодарский край. типы в меню: Брют, Полусухое, Полусладкое; крепость: 12,5% Брют - минимальное количество сахара (до 12 г/л.). Вкус: освежающий, гармоничный, с легкой цитрусовой кислинкой и минеральными нотками. Полусухое - средний уровень сахара (17–35 г/л.). Вкус: сбалансированный, мягкий, с доминирующими тонами зеленого яблока, спелой груши и легким медовым послевкусием. Полусладкое - более высокий уровень сахара (33–50 г/л). Вкус: яркий, полный, с нотами белого персика, спелых фруктов и меда, уравновешенный приятной кислинкой. Послевкусие фруктово-цветочное. Виноград: шардоне, рислинг, совиньон блан, пино блан, алиготе. Эндемы Ркацители брют - белое игристое; страна: Россия, Дагестан. Крепость: 12,5% Вкус: Питкий, чистый и освежающий. Проявляется живая фруктовая кислотность и минеральность с выраженными нотами зеленого яблока и дикой груши. Виноград - 100% Ркацители. Bio Bio Bubbles brut (Био Био Бабблс брют) - белое игристое; страна: Италия, Сицилия. Крепость: 11% Вкус: Очень легкий, мягкий. Во вкусе свежие цитрусовые ноты, зеленое яблоко и легкий миндальный оттенок в послевкусии. Обладает деликатной, неагрессивной кислинкой. Виноград - Белый купаж из двух сортов — Гарганега и Инзолия. Вино является органическим (био). Эко — это вино, произведенное с заботой об окружающей среде, при выращивании которого минимизировано или полностью исключено использование химических удобрений и пестицидов. На винодельне процесс также контролируется: снижается выброс углекислого газа, экономно расходуется вода и используется экологичная упаковка.< Bruni Asti (Бруни Асти) - белое сладкое игристое; страна: Италия, Пьемонт. Крепость: 7,5% Вкус: Яркий, освежающий, умеренная кислотность. Во вкусе и аромате выраженные ноты спелого абрикоса, белых цветов и легкие нотки лайма. Сладость не приторная. Виноград: 100% Мускат Белый Bruni Prosecco extra dry (Бруни Просекко экстра драй) - белое игристое; страна: Италия, Венето. Крепость: 11% Вкус: Свежий, легкий, гармоничный и очень питкий. Во вкусе и аромате оттенки зеленого яблока, спелой груши, белого персика. Виноград: 100% Глера Cava Dos Caprichos Brut (Кава Дос Капричос брют) - белое игристое; страна: Испания, Каталония. Крепость: 11,5% Вкус: Свежий и сухой. Во вкусе и аромате яркие яблочно-цитрусовые оттенки, ноты белого персика и полевых цветов. Обладает сбалансированной кислотностью и минеральностью. Виноград: Макабео, Парельяда и Чарелло Lunetta Prosecco Rose Extra Dry (Лунетта Просекко Розе Экстра драй) - розовое игристое; страна: Италия, Венето. Крепость: 11% Вкус: Легкий, сбалансированный. Округлая фруктовая сладость, которая сглаживает кислотность. Во вкусе и аромате яркий ягодный профиль: малина, клубника, вишня и красная смородина. Виноград: Глера, Пино Нуар Pet-Nat Nobles Et Guilotines Rose Brut (Пет-Нат Ноблес и Гильотинес Розе брют) - розовое игристое; страна: Испания, Каталония. Крепость: 11% Вкус: Свежий, сочный и легкий. В нем преобладает яркая ягодная доминанта: выразительные ноты кислой вишни, спелой клубники, малины и гранатового сока. Виноград: 100% Темпранильо Andre Delorme Cremant de Bourgogne Brut (Андре Делорме Креман де Бургонь брют) - белое игристое; страна: Франция, Бургундия. Крепость: 12% Вкус: Округлый и глубокий. Живая освежающая кислотность. Во вкусе ноты зеленого яблока, спелой груши, персика и цукатов. Благодаря долгой выдержке в послевкусии свежая хлебная корочка (бриошь) Виноград: Шардоне, Алиготе, Пино Нуар и Гаме. Используется виноград исключительно ручного сбора и только сок первого отжима (кюве).',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
