insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-11_block_30','lesson-11',290,'paragraph','Вкус: Округлый и глубокий. Живая освежающая кислотность. Во вкусе ноты зеленого яблока, спелой груши, персика и цукатов. Благодаря долгой выдержке в послевкусии свежая хлебная корочка (бриошь)
