insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-12','Вино','Розовые вина "BeerBistro"','- Le Grand Noir Rose (Ле Гран Нуар Розе) - "тихое" сухое розовое вино; страна: Франция, Лангедок-Руссильон. Крепость: 12,5% Вкус:Свежий, легкий, с нотами клубники, малины…','published',120,false,'Розовые вина "BeerBistro" Вино - Le Grand Noir Rose (Ле Гран Нуар Розе) - "тихое" сухое розовое вино; страна: Франция, Лангедок-Руссильон. Крепость: 12,5% Вкус:Свежий, легкий, с нотами клубники, малины… Le Grand Noir Rose (Ле Гран Нуар Розе) - "тихое" сухое розовое вино; страна: Франция, Лангедок-Руссильон. Крепость: 12,5% Вкус:Свежий, легкий, с нотами клубники, малины и приятной ягодной кислинкой. Виноград: Гренаш, Сира/Шираз Paddle Creek Riesling Rose (Паддл Крик Рислинг Розе) - "тихое" розовое вино; страна: Новая Зеландия, Мальборо. Крепость: 12% Вино Paddle Creek Riesling Rose официально классифицируется в России как полусухое, однако в некоторых каталогах и описаниях прошлых винтажей его иногда ошибочно или из-за особенностей восприятия называют полусладким. В меню BeerBistro оно записано как "полусухое/полусладкое". Вкус: Живая хрустящая кислинка, которая идеально балансирует природную сладость рислинга. Чувствуются легкие оттенки белых фруктов и смородины. В аромате спелый перец, малина и легкие луговые травы. Виноград: белый сорт Рислинг (97%) с добавлением капли красного сорта Пино Нуар (3%) для придания нежного розового оттенка.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
