insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-13','Вино','Оранжевое вино "BeerBistro"','- Lunaria Ancestrale Malvasia Orange (Лунария Анчестрале Мальвазия Оранж) - тихое оранжевое полусухое вино; страна: Италия, Абруццо. Крепость: 13,% Вкус: Сбалансированный…','published',130,false,'Оранжевое вино "BeerBistro" Вино - Lunaria Ancestrale Malvasia Orange (Лунария Анчестрале Мальвазия Оранж) - тихое оранжевое полусухое вино; страна: Италия, Абруццо. Крепость: 13,% Вкус: Сбалансированный… Lunaria Ancestrale Malvasia Orange (Лунария Анчестрале Мальвазия Оранж) - тихое оранжевое полусухое вино; страна: Италия, Абруццо. Крепость: 13,% Вкус: Сбалансированный, с живой кислотностью. Обладает характерным для оранжей сладковато-горьковатым профилем (ноты белого изюма переходят в благородную легкую горчинку грейпфрутовой корочки) и легкой, вяжущей танинной терпкостью в послевкусии. Аромат: Сложный, яркий и парфюмированный. Доминируют цедра лимона и апельсина, курага, сухие цветы, дикая роза, а также нотки сухого сена, аниса и легкие дрожжевые нотки (так как вино не фильтруется). Виноград: 100% Мальвазия *Оранжевое вино (Orange wine, также Amber wine или янтарное вино) — это белое вино, произведенное по технологии красного вина. Это не новый тренд, а возвращение к древнейшим истокам виноделия, которым более 8 000 лет. Контакт с кожицей может давать насыщенный вкус и танинную терпкость. Оранжевый цвет сам по себе не означает, что вино органическое, нефильтрованное или сброжено без контроля температуры. Подавать его стоит при температуре 10–12 °C к жирной рыбе, птице, восточной кухне со специями или зрелым сырам*',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
