insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-13_block_4','lesson-13',30,'paragraph','*Оранжевое вино (Orange wine, также Amber wine или янтарное вино) — это белое вино, произведенное по технологии красного вина. Это не новый тренд, а возвращение к древнейшим истокам виноделия, которым более 8 000 лет.
insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-14','Вино','Белое вино "BeerBistro"','- SanVigilio Pinot Grigio (СанВиджилио Пино Гриджио) - СУХОЕ белое вино; страна: Италия, Ломбардия. Крепость:12% Вкус: Легкий, с хрустящей кислинкой, минеральными оттенка…','published',140,false,'Белое вино "BeerBistro" Вино - SanVigilio Pinot Grigio (СанВиджилио Пино Гриджио) - СУХОЕ белое вино; страна: Италия, Ломбардия. Крепость:12% Вкус: Легкий, с хрустящей кислинкой, минеральными оттенка… SanVigilio Pinot Grigio (СанВиджилио Пино Гриджио) - СУХОЕ белое вино; страна: Италия, Ломбардия. Крепость:12% Вкус: Легкий, с хрустящей кислинкой, минеральными оттенками и чистым сухим послевкусием. В аромате зеленое яблоко, груша, луговые травы и лимонная цедра. Виноград: 100% Пино Гриджио Ocean Buffet Vinho Verde (Оушен Буффе Винью Верде) - ПОЛУСУХОЕ белое вино; страна: Португалия, Винью Верде. Крепость: 10% Вкус: Освежающий, «хрустящий», с фирменной для Винью Верде легкой естественной газацией (микропузырьками). Во вкусе раскрываются фруктово-минеральные оттенки с приятной цитрусовой кислинкой. Виноград: Аринту и Лоурейру Bastianich Vigne Orsone Sauvignon (Бастианич Винье Орсоне Совиньон) - СУХОЕ белое вино; страна: Италия, Фриули-Венеция-Джулиа. Крепость: 12,5% Вкус: Абсолютно сухой, с яркой, хрустящей и сочной кислотностью. Обладает выразительной минеральной текстурой и долгим, чистым цитрусово-фруктовым послевкусием. Виноград: 100% Совиньон Блан Badet Clement Les Jamelles Sauvignon Blanc (Баде Клеман Ле Жамель Совиньон Блан) - СУХОЕ белое вино; страна: Франция, Лангедок-Руссильон. Крепость: 12,5% Вкус: Освежающий, с хорошо сбалансированной, хрустящей кислотностью. Обладает приятным, чистым и долгим послевкусием с легкой цитрусовой горчинкой. Виноград: 100% Совиньон Блан Winzer von Erbach Riesling (Винцер фон Эрбах Рислинг) - ПОЛУСУХОЕ белое вино; страна: Германия, Рейнгау. Крепость: 12% Вкус: Насыщенный с выразительной, хрустящей кислотностью, которая идеально сбалансирована фруктовыми тонами. Вино обладает чистым и «солоновато»-минеральным послевкусием. Виноград: 100% Рислинг Dourthe «Grands Terroirs» Bordeaux Blanc (Дурт «Гран Терруар» Бордо Блан) - ПОЛУСЛАДКОЕ белое вино; страна: Франция, Бордо. Крепость: 11% Вкус: Округлый, нежный и мягкий вкус с деликатной природной сладостью, которая сбалансирована освежающей фруктовой кислинкой, не дающей вину стать приторным. Виноград: Совиньон Блан, Семильон и Мюскадель Santa Carolina Chardonnay (Санта Каролина Шардоне) - ПОЛУСУХОЕ белое вино; страна: Чили, Центральная долина. Крепость: 12,5% Вкус: Округлый, мягкий, с сочной фруктовой кислинкой, нежной маслянисто-кремовой текстурой и коротким, освежающим сладковатым финалом. Виноград: 100% Шардоне Ramon Bilbao Enaria (Рамон Бильбао Энария) - СУХОЕ белое вино; страна: Испания, Руэда. Крепость: 12,5% Вкус: Легкий, шелковистый вкус с яркой цитрусовой кислотностью, чистыми фруктово-минеральными оттенками и бодрящим, гармоничным послевкусием. Виноград: 100% Вердехо Misty Cliff Sauvignon Blanc (Мисти Клифф Совиньон Блан) - ПОЛУСУХОЕ белое вино; страна: Новая Зеландия, Мальборо. Крепость: 12,5% Вкус: Мягкий и сочный вкус с выразительными фруктово-цитрусовыми акцентами, хрустящей живой кислинкой, гладкой текстурой и долгим, освежающим тропическим послевкусием. Виноград: 100% Совиньон Блан Gruner Veltliner Kremstal (Грюнер Вельтлинер Кремсталь) - СУХОЕ белое вино; страна: Австрия, Нижняя Австрия. Крепость: 12,5% Вкус: Сбалансированный, питкий вкус наполнен дымными и травяными штрихами, которые дополняются кремовой текстурой и завершаются долгим послевкусием с акцентами тимьяна и чечевицы. Виноград: 100% Грюнер Вельтлинер Alex Gambal Fixin (Алекс Гамбал Фиксен) - СУХОЕ белое вино; страна: Франция, Бургундия. Крепость: 12,5% Вкус: Прекрасно сбалансированный, с богатой шелковистой текстурой и долгим, щедрым послевкусием с фруктовыми и минеральными оттенками. Виноград: 100% Шардоне Black Stallion Chardonnay (Блэк Стэллион Шардоне) - СУХОЕ белое вино; страна: США, долина Напа. Крепость: 14,5% Вкус: Свежий, гармоничный, с тонами спелых косточковых фруктов, сливок и пралине, хрустящей кислинкой. Виноград: 100% Шардоне',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
