insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-14_block_11','lesson-14',100,'paragraph','Вкус: Освежающий, с хорошо сбалансированной, хрустящей кислотностью. Обладает приятным, чистым и долгим послевкусием с легкой цитрусовой горчинкой.
