insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-14_block_14','lesson-14',130,'paragraph','Вкус: Насыщенный с выразительной, хрустящей кислотностью, которая идеально сбалансирована фруктовыми тонами. Вино обладает чистым и «солоновато»-минеральным послевкусием.
