insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-14_block_17','lesson-14',160,'paragraph','Вкус: Округлый, нежный и мягкий вкус с деликатной природной сладостью, которая сбалансирована освежающей фруктовой кислинкой, не дающей вину стать приторным.
