insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-14_block_26','lesson-14',250,'paragraph','Вкус: Мягкий и сочный вкус с выразительными фруктово-цитрусовыми акцентами, хрустящей живой кислинкой, гладкой текстурой и долгим, освежающим тропическим послевкусием.
