insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-14_block_29','lesson-14',280,'paragraph','Вкус: Сбалансированный, питкий вкус наполнен дымными и травяными штрихами, которые дополняются кремовой текстурой и завершаются долгим послевкусием с акцентами тимьяна и чечевицы.
