insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-15','Вино','Красное вино "BeerBistro"','- Altisano Rosso (Альтизано Россо) - СУХОЕ красное вино; страна: Италия, Эмилия-Романья. Крепость: 11% Вкус: Вино обладает тонким телом, высокой ягодной кислинкой и мягки…','published',150,false,'Красное вино "BeerBistro" Вино - Altisano Rosso (Альтизано Россо) - СУХОЕ красное вино; страна: Италия, Эмилия-Романья. Крепость: 11% Вкус: Вино обладает тонким телом, высокой ягодной кислинкой и мягки… Altisano Rosso (Альтизано Россо) - СУХОЕ красное вино; страна: Италия, Эмилия-Романья. Крепость: 11% Вкус: Вино обладает тонким телом, высокой ягодной кислинкой и мягкими, едва заметными бархатистыми танинами. Виноград: Санджовезе, Мерло Rondone Chianti (Рондоне Кьянти) - СУХОЕ красное вино; страна: Италия, Тоскана. Крепость: 13% Вкус: Главная фишка вкуса — классический для Кьянти профиль спелой вишневой косточки, переходящий в суховатый финиш с пикантной горчинкой. Виноград: 100% Санджовезе Primasole Primitivo (Примасоле Примитиво) - ПОЛУСУХОЕ красное вино; страна: Италия, Апулия. Крепость: 13% Вкус: Во вкусе доминирует мощный концентрированный тон спелой черешни и черничного варенья, оставляющий теплое, сладковато-пряное и мягкое послевкусие. Виноград: 100% Примитиво Besini Kindzmarauli (Бесини Киндзмараули) - ПОЛУСЛАДКОЕ красное вино; страна: Грузия, Кахетия. Крепость: 11,5% Вкус: Главная особенность вкуса — идеальный баланс: яркая природная сладость чернично-ежевичного джема мгновенно уравновешивается сочной, освежающей кислинкой свежей гранатовой корки. Виноград: 100% Саперави Santa Carolina Carmenere (Санта Каролина Карменер) - ПОЛУСУХОЕ красное вино; страна: Чили, Центральная долина. Крепость: 13,5% Вкус: В основе вкуса лежит густой профиль спелой черной вишни и ежевики, который на финише сменяется узнаваемой, пикантной и согревающей волной белого и черного перца. Виноград: 100% Карменер Les Classiques de France (Ле Классик де Франс) - СУХОЕ красное вино; страна: Франция, Бордо. Крепость: 12% Вкус: Во вкусе доминирует простой профиль недозрелой красной вишни и лесных ягод, оставляющий короткий, нейтральный и слегка сушащий финиш.. Виноград: Мерло, Гренаш и Кариньян Ramon Bilbao Crianza (Рамон Бильбао Крианса) - СУХОЕ красное вино; страна: Испания, Риоха. Крепость: 14% Вкус: Ягодная свежесть, живая кислотность. На послевкусии пикантные тона пряностей, дыма и благородного дерева. Виноград: 100% Темпранильо Appassimento Segreto Rosso (Аппассименто Сегрето Россо) - ПОЛУСУХОЕ красное вино; страна: Италия, Апулия. Крепость: 14% Вкус: Главная фишка вкуса — сиропно-джемовая плотность черничного варенья и спелой вишни, которая переходит в долгое, согревающее послевкусие с акцентом на сладкий горький шоколад и чашечку эспрессо. Виноград: 100% Негроамаро Two Hands «Gnarly Dudes» Shiraz (Ту Хэндс «Нэли Дюдс» Шираз) - СУХОЕ красное вино; страна: Австралия, Долина Баросса. Крепость: 14% Вкус: Мясистый профиль чернично-ежевичного джема и вяленой сливы, переходящий в долгое, согревающее послевкусие с сильным акцентом на черный молотый перец, угольную пыль, копченое мясо и горький шоколад. Виноград: 100% Шираз Joseph Drouhin «Laforet» Bourgogne Pinot Noir (Жозеф Друэн «Лафоре» Бургонь Пино Нуар) - СУХОЕ красное вино; страна: Франция, Бургундия. Крепость: 13% Вкус: Во вкусе раскрывается чистый, хрустящий профиль свежей лесной малины, дикой земляники и клюквы, который оставляет элегантное, сухое и полупрозрачное послевкусие. Виноград: 100% Пино Нуар Vietti Barolo «Castiglione» (Виетти Бароло «Кастильоне») - СУХОЕ красное вино; страна: Италия, Пьемонт. Крепость: 14% Вкус: Фруктовость здесь не сладкая: доминирует сухой профиль дикой клюквы, барбариса и горькой вишни. Виноград: 100% Неббиоло',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
