insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-15_block_23','lesson-15',220,'paragraph','Вкус: Главная фишка вкуса — сиропно-джемовая плотность черничного варенья и спелой вишни, которая переходит в долгое, согревающее послевкусие с акцентом на сладкий горький шоколад и чашечку эспрессо.
