insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-16','Вино','Безалкогольное вино "BeerBistro"','- Hans Baer Riesling Alcohol Free (Ханс Баер Рислинг Безалкогольное) - ПОЛУСУХОЕ белое безалкогольное вино; страна: Германия, Пфальц. Крепость: менее 0,5% Вкус: Ультрасве…','published',160,false,'Безалкогольное вино "BeerBistro" Вино - Hans Baer Riesling Alcohol Free (Ханс Баер Рислинг Безалкогольное) - ПОЛУСУХОЕ белое безалкогольное вино; страна: Германия, Пфальц. Крепость: менее 0,5% Вкус: Ультрасве… Hans Baer Riesling Alcohol Free (Ханс Баер Рислинг Безалкогольное) - ПОЛУСУХОЕ белое безалкогольное вино; страна: Германия, Пфальц. Крепость: менее 0,5% Вкус: Ультрасвежий, легкий, «колкий» и хрустящий. В описании этой позиции на первый план выходит свежая кислотность зелёного яблока. Деалкоголизация сама по себе не означает отсутствие глицерина; остаточный алкоголь проверяем по этикетке. Виноград: 100% Рислинг',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-16_block_1','lesson-16',0,'list',null,'[]'::jsonb,null,false,'[{"text":"Hans Baer Riesling Alcohol Free (Ханс Баер Рислинг Безалкогольное) - ПОЛУСУХОЕ белое безалкогольное вино; страна: Германия, Пфальц. Крепость: менее 0,5%","marks":[{"type":"bold","from":0,"to":31}]}]'::jsonb,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-16_block_2','lesson-16',10,'paragraph','Вкус: Ультрасвежий, легкий, «колкий» и хрустящий. В описании этой позиции на первый план выходит свежая кислотность зелёного яблока. Деалкоголизация сама по себе не означает отсутствие глицерина; остаточный алкоголь проверяем по этикетке.
insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-17','Сервис','Семь шагов: встреча, меню и принятие заказа','Задача первых минут — дать гостю почувствовать, что ему рады. Приветствуют все сотрудники, которые заметили гостя. Если вы уже разговариваете с другим гостем, достаточно…','published',170,false,'Семь шагов: встреча, меню и принятие заказа Сервис Задача первых минут — дать гостю почувствовать, что ему рады. Приветствуют все сотрудники, которые заметили гостя. Если вы уже разговариваете с другим гостем, достаточно… Задача первых минут — дать гостю почувствовать, что ему рады. Приветствуют все сотрудники, которые заметили гостя. Если вы уже разговариваете с другим гостем, достаточно улыбки и кивка. Семь этапов обслуживания. Схема из материала «БФ 7 шагов» 1. Встречаем и провожаем Поздоровайтесь и предложите пройти к столу. Не начинайте с очереди вопросов «Вы один? Бронировали?». Необходимые уточнения задайте после приветствия, спокойно и по делу. Предложите пару подходящих мест. Учитывайте пожелания гостя и равномерную рассадку. Если выбранный им стол свободен и доступен для посадки, помогите расположиться именно там. Встреча гостя. Иллюстрация из «БФ 7 шагов» 2. Подаём меню Подайте меню, когда гость сел и готов слушать. По стандарту из материала меню дают каждому: сначала детям, затем женщинам от старшей к младшей, затем мужчинам. Коротко расскажите об одной подходящей позиции: «У нас есть пиво собственной варки». Это «удочка» — полезный анонс, а не требование немедленно заказать. Вместо «Вам что-то сразу?» скажите: «Выбирайте, я скоро к вам вернусь». 3. Принимаем заказ Гость оторвался от меню и поднял взгляд — подойдите. Не заставляйте его искать сотрудника или махать рукой. Сначала выясните предпочтения: «Какое блюдо вам хочется?» Помогите сузить выбор: «Предпочитаете мясо или рыбу?» Запишите заказ отдельно по каждому гостю. Предложите недостающую позицию, если она уместна. Повторите заказ в последовательности подачи. Вместо «Вам по готовности?» — «Сначала принесём напитки, затем закуски и горячее». Если у гостя другой план, согласуйте порядок. Если гость торопится или приготовление выйдет за обычные сроки, заранее назовите реальное время. После заказа заберите лишние меню, одно оставьте. Если нужно забрать все, предложите принести меню снова по просьбе. Источник: «БФ 7 шагов», страницы 1–4.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
