insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-17_block_15','lesson-17',140,'paragraph','Если гость торопится или приготовление выйдет за обычные сроки, заранее назовите реальное время. После заказа заберите лишние меню, одно оставьте. Если нужно забрать все, предложите принести меню снова по просьбе.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-17_block_16','lesson-17',150,'paragraph','Источник: «БФ 7 шагов», страницы 1–4.','[{"type":"italic","from":0,"to":37}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-18','Сервис','Заказ в системе и аккуратная подача','Хорошая подача начинается с правильно записанного заказа. Вносите его в систему по гостям, указывайте актуальное число гостей и задавайте курсы отдельно каждому. Обычная…','published',180,false,'Заказ в системе и аккуратная подача Сервис Хорошая подача начинается с правильно записанного заказа. Вносите его в систему по гостям, указывайте актуальное число гостей и задавайте курсы отдельно каждому. Обычная… Хорошая подача начинается с правильно записанного заказа. Вносите его в систему по гостям, указывайте актуальное число гостей и задавайте курсы отдельно каждому. Обычная последовательность из стандарта: напитки, закуски, салаты, супы, горячее, десерт. Пожелания гостя согласуйте и отразите в заказе. Как держать посуду Чашку — за ручку, бокал — за ножку. Предмет без ручки и ножки — за нижнюю часть. Приборы — за половину ручки. Тарелку — только за борт. Не касайтесь части посуды, с которой соприкасаются губы гостя или еда. Это относится и к использованной посуде. Не прижимайте тарелки к одежде и не переносите предметы ниже бедра. Зоны работы с посудой. Иллюстрация из «БФ 7 шагов» Как подать заказ Подойдите так, чтобы гость видел вас. Не ставьте блюдо через плечо и не тянитесь поперёк стола. Подайте блюдо тому, кто его заказал, и назовите его. Согласованные курсы старайтесь подавать одновременно всем гостям. Если нужно перенести больше двух предметов, возьмите поднос. Держите его на руке; не ставьте на гостевой стол или диван, не зажимайте подмышкой. Стол — пространство гостя. Предупреждайте, прежде чем что-то поставить или убрать. После протирки поверхность должна быть сухой. Источник: «БФ 7 шагов», страницы 5–6.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
