insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-18_block_5','lesson-18',40,'paragraph','Не касайтесь части посуды, с которой соприкасаются губы гостя или еда. Это относится и к использованной посуде. Не прижимайте тарелки к одежде и не переносите предметы ниже бедра.','[{"type":"highlight","from":0,"to":70}]'::jsonb,null,null,null,null,null,'','','');
