insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-18_block_8','lesson-18',70,'paragraph','Подойдите так, чтобы гость видел вас. Не ставьте блюдо через плечо и не тянитесь поперёк стола. Подайте блюдо тому, кто его заказал, и назовите его. Согласованные курсы старайтесь подавать одновременно всем гостям.','[]'::jsonb,null,null,null,null,null,'','','');
