insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-19','Сервис','Обратная связь, повтор заказа и завершение визита','Не ждите жалобы: спросите, как гостю блюдо. Лучший момент — после того, как он попробовал. Особенно важно проверить свою рекомендацию. Собирайте обратную связь по каждой…','published',190,false,'Обратная связь, повтор заказа и завершение визита Сервис Не ждите жалобы: спросите, как гостю блюдо. Лучший момент — после того, как он попробовал. Особенно важно проверить свою рекомендацию. Собирайте обратную связь по каждой… Не ждите жалобы: спросите, как гостю блюдо. Лучший момент — после того, как он попробовал. Особенно важно проверить свою рекомендацию. Собирайте обратную связь по каждой позиции; для большой компании допустимо спросить о курсе в целом. При высокой загрузке вернитесь к вопросу при подаче следующего курса или уборке посуды. Если ответ неясный «Нормально» и «пойдёт» не всегда означают, что всё понравилось. Спокойно уточните: «Что хотелось бы изменить?» Если гость не ест, не делайте вывод самостоятельно — спросите о причине. На замечание реагируйте по LAST или LATTE. Если не знаете, как решить ситуацию, выслушайте, извинитесь и подключите менеджера. Положительную обратную связь тоже передавайте коллегам. Предложение в нужный момент Когда остаётся примерно треть напитка, можно предложить повтор или другой подходящий вариант. Отказ гостя принимаем спокойно. Если напитки есть, а закуски закончились, уместно предложить закуску; после горячего — десерт. Перед расчётом спросите и о впечатлении в целом: «Как прошёл вечер?» При подходящей ситуации предложите заказ с собой. Упоминайте скидку только после проверки действующих условий. Счёт и прощание Передайте счёт тому, кто его попросил. По стандарту из материала не зачитывайте заказ и сумму вслух без просьбы. Не пропадайте после оплаты: гость всё ещё у вас. Тепло попрощайтесь и при желании предложите идею для следующего визита. Пока гости сидят, аккуратно поддерживайте порядок. Полную уборку и пересервировку начинайте после их ухода: приведите в порядок стол и сиденья, при мусоре на полу пригласите клининг. Последний бокал не забирайте автоматически: учитывайте его состояние и ситуацию на столе. Источник: «БФ 7 шагов», страницы 7–10.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
