insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-19_block_8','lesson-19',70,'paragraph','Перед расчётом спросите и о впечатлении в целом: «Как прошёл вечер?» При подходящей ситуации предложите заказ с собой. Упоминайте скидку только после проверки действующих условий.','[]'::jsonb,null,null,null,null,null,'','','');
