insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-19_block_10','lesson-19',90,'list',null,'[]'::jsonb,null,false,'[{"text":"Передайте счёт тому, кто его попросил.","marks":[]},{"text":"По стандарту из материала не зачитывайте заказ и сумму вслух без просьбы.","marks":[]},{"text":"Не пропадайте после оплаты: гость всё ещё у вас.","marks":[]},{"text":"Тепло попрощайтесь и при желании предложите идею для следующего визита.","marks":[]}]'::jsonb,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-19_block_11','lesson-19',100,'paragraph','Пока гости сидят, аккуратно поддерживайте порядок. Полную уборку и пересервировку начинайте после их ухода: приведите в порядок стол и сиденья, при мусоре на полу пригласите клининг. Последний бокал не забирайте автоматически: учитывайте его состояние и ситуацию на столе.','[]'::jsonb,null,null,null,null,null,'','','');
