insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-20','Сервис','Как помочь выбрать: вопросы и рекомендации','Продажа начинается с понимания желания гостя. Сначала узнайте, что ему подходит, затем предложите понятный вариант. Три вида вопросов - Открытый: «Какие напитки вам нравя…','published',200,false,'Как помочь выбрать: вопросы и рекомендации Сервис Продажа начинается с понимания желания гостя. Сначала узнайте, что ему подходит, затем предложите понятный вариант. Три вида вопросов - Открытый: «Какие напитки вам нравя… Продажа начинается с понимания желания гостя. Сначала узнайте, что ему подходит, затем предложите понятный вариант. Три вида вопросов Открытый: «Какие напитки вам нравятся?» — нужен развёрнутый ответ. Альтернативный: «Чай или кофе?» — выбор между вариантами. Закрытый: «Готовим для вас этот салат?» — подтверждение «да» или «нет». Вопрос «Вы любите шоколад?» — закрытый. В исходной презентации он оказался среди открытых; здесь классификация исправлена. Воронка и «ёлочка» Воронка ведёт от общего к точному: «Чем хотите пообедать?» → «Мясом или рыбой?» → «Тогда готовим выбранное блюдо?» «Ёлочка» — несколько коротких альтернативных вопросов. Достаточно нескольких уточнений, чтобы прийти к рекомендации; не превращайте беседу в опрос. Пример «ёлочки» вопросов из материала «Техники продаж» Как описать блюдо Назовите основной продукт, способ приготовления, соус и заметную особенность вкуса или текстуры. Например: «Хрустящие гренки с чесноком, к ним подаём сырный соус». Не выдумывайте состав, личный опыт дегустации или отзывы гостей. Если сомневаетесь, уточните информацию. Подборка слов для описания блюд из исходного материала «Гости часто хвалят» используйте, когда это правда. Личная рекомендация помогает выбрать между двумя вариантами, но должна соответствовать предпочтениям гостя. Источник: «Техники продаж», страницы 1–7.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_1','lesson-20',0,'paragraph','Продажа начинается с понимания желания гостя. Сначала узнайте, что ему подходит, затем предложите понятный вариант.','[{"type":"bold","from":0,"to":45}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_2','lesson-20',10,'heading','Три вида вопросов','[]'::jsonb,2,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_3','lesson-20',20,'list',null,'[]'::jsonb,null,false,'[{"text":"Открытый: «Какие напитки вам нравятся?» — нужен развёрнутый ответ.","marks":[{"type":"bold","from":0,"to":9}]},{"text":"Альтернативный: «Чай или кофе?» — выбор между вариантами.","marks":[{"type":"bold","from":0,"to":15}]},{"text":"Закрытый: «Готовим для вас этот салат?» — подтверждение «да» или «нет».","marks":[{"type":"bold","from":0,"to":9}]}]'::jsonb,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_4','lesson-20',30,'paragraph','Вопрос «Вы любите шоколад?» — закрытый. В исходной презентации он оказался среди открытых; здесь классификация исправлена.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_5','lesson-20',40,'heading','Воронка и «ёлочка»','[]'::jsonb,2,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_6','lesson-20',50,'paragraph','Воронка ведёт от общего к точному: «Чем хотите пообедать?» → «Мясом или рыбой?» → «Тогда готовим выбранное блюдо?»','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_7','lesson-20',60,'paragraph','«Ёлочка» — несколько коротких альтернативных вопросов. Достаточно нескольких уточнений, чтобы прийти к рекомендации; не превращайте беседу в опрос.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_8','lesson-20',70,'image',null,'[]'::jsonb,null,null,null,null,'assets/service-images/sales-3-2.jpg','Пример «ёлочки» вопросов из материала «Техники продаж»','','');
