insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_10','lesson-20',90,'paragraph','Назовите основной продукт, способ приготовления, соус и заметную особенность вкуса или текстуры. Например: «Хрустящие гренки с чесноком, к ним подаём сырный соус».','[{"type":"italic","from":107,"to":163}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_11','lesson-20',100,'paragraph','Не выдумывайте состав, личный опыт дегустации или отзывы гостей. Если сомневаетесь, уточните информацию.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_12','lesson-20',110,'image',null,'[]'::jsonb,null,null,null,null,'assets/service-images/sales-5-1.jpg','Подборка слов для описания блюд из исходного материала','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_13','lesson-20',120,'paragraph','«Гости часто хвалят» используйте, когда это правда. Личная рекомендация помогает выбрать между двумя вариантами, но должна соответствовать предпочтениям гостя.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-20_block_14','lesson-20',130,'paragraph','Источник: «Техники продаж», страницы 1–7.','[{"type":"italic","from":0,"to":41}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-21','Сервис','Уместные продажи: дополнения, «удочка» и альтернатива','Предлагаем то, что улучшит заказ, и оставляем гостю свободу отказаться. Дополнения и сочетания - Недостающая позиция: к заказанному блюду ещё не выбрали напиток — предлож…','published',210,false,'Уместные продажи: дополнения, «удочка» и альтернатива Сервис Предлагаем то, что улучшит заказ, и оставляем гостю свободу отказаться. Дополнения и сочетания - Недостающая позиция: к заказанному блюду ещё не выбрали напиток — предлож… Предлагаем то, что улучшит заказ, и оставляем гостю свободу отказаться. Дополнения и сочетания Недостающая позиция: к заказанному блюду ещё не выбрали напиток — предложите подходящий. Доп: дополнительный ингредиент к выбранной позиции. Комбо: удачное сочетание самостоятельных блюд и напитков. Цепочка: к напитку предложили закуску, затем подходящее дополнение к ней. Проверяйте актуальную доступность и стоимость дополнений. Не добавляйте ничего без согласия. Короткая «удочка» Это небольшой анонс: «Кстати, у нас появился новый чай». Выбирайте предложение по ситуации: погоде, времени визита и словам гостя. «Удочка» как короткий анонс. Иллюстрация из «Техники продаж» На следующий визит предлагайте то, что связано с сегодняшним удачным выбором. Если понравилось одно блюдо, расскажите о близком по вкусу варианте. Как выделить рекомендацию В приёме «первое — последнее» основную рекомендацию называют в начале и конце короткого списка. В методе Штирлица акцентный вариант ставят в конец и поясняют, почему он подходит. Лёгкий кивок может поддержать рекомендацию, но не заменяет аргумент и согласие гостя. Если позиция закончилась Не ограничивайтесь словом «нет». Предложите близкую альтернативу и объясните сходство: по продукту, вкусу, сытности или способу приготовления. Если гость отказался, не повторяйте предложение настойчиво. «Золотой момент» — вовремя заметить потребность: замёрзшему гостю предложить согревающий напиток, спешащему помочь выбрать быстрое блюдо. Обещания должны соответствовать возможностям кухни и бара. Источник: «Техники продаж», страницы 3–4 и 6–13.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
