insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-22','Сервис','Фразы, которые помогают гостю','Говорим спокойно, понятно и с готовностью помочь. Главное в замене фразы — не заученная вежливость, а следующее действие. - Вместо «Я не знаю» — «Я уточню и вернусь к вам…','published',220,false,'Фразы, которые помогают гостю Сервис Говорим спокойно, понятно и с готовностью помочь. Главное в замене фразы — не заученная вежливость, а следующее действие. - Вместо «Я не знаю» — «Я уточню и вернусь к вам… Говорим спокойно, понятно и с готовностью помочь. Главное в замене фразы — не заученная вежливость, а следующее действие. Иллюстрация из материала «Запрещенные фразы» Вместо «Я не знаю» — «Я уточню и вернусь к вам». Назовите срок, который сможете соблюсти. Вместо «У нас всё вкусно» — конкретная рекомендация с коротким описанием. Вместо «Нет» — «Эта позиция закончилась, могу предложить…». Вместо «И это всё?» — «Спасибо за заказ». Вместо «Ого, сколько!» — «Отличный выбор», если такая реакция уместна. Вместо «Грязная посуда» — «Пустая посуда» или просьба разрешить убрать тарелку. Вместо «Повар виноват» — «Это наша недоработка, сейчас разберёмся». Вместо «Я не ваш официант» — «Я вас слушаю», затем помогите или передайте просьбу ответственному сотруднику. Вместо «У нас запара» — «Сейчас высокая загрузка» и конкретная информация об ожидании. Вместо «Вам по готовности?» — повтор заказа по согласованным курсам. Обычная грамотная речь Говорим «Здравствуйте», «Добрый вечер», «Пожалуйста». Называем гостей «гость», «гостья», «гости». Используем слова «суп», «салат», «бокал», «заказ» без постоянных уменьшительных суффиксов. Не перечисляйте обрывками «Сироп? Сахар? Корица?». Сформулируйте полное предложение: «Какой сироп добавим в кофе?» — если гость уже выразил интерес к добавке. Если кухня закрыта, объясните, что ещё действительно можно заказать. Не обещайте блюдо или десерт, не проверив доступность. Источник: «Запрещенные фразы», страницы 1–5.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
