insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-22_block_3','lesson-22',20,'list',null,'[]'::jsonb,null,false,'[{"text":"Вместо «Я не знаю» — «Я уточню и вернусь к вам». Назовите срок, который сможете соблюсти.","marks":[{"type":"bold","from":21,"to":47}]},{"text":"Вместо «У нас всё вкусно» — конкретная рекомендация с коротким описанием.","marks":[{"type":"bold","from":28,"to":51}]},{"text":"Вместо «Нет» — «Эта позиция закончилась, могу предложить…».","marks":[{"type":"bold","from":15,"to":58}]},{"text":"Вместо «И это всё?» — «Спасибо за заказ».","marks":[{"type":"bold","from":22,"to":40}]},{"text":"Вместо «Ого, сколько!» — «Отличный выбор», если такая реакция уместна.","marks":[{"type":"bold","from":25,"to":41}]},{"text":"Вместо «Грязная посуда» — «Пустая посуда» или просьба разрешить убрать тарелку.","marks":[{"type":"bold","from":26,"to":41}]},{"text":"Вместо «Повар виноват» — «Это наша недоработка, сейчас разберёмся».","marks":[{"type":"bold","from":25,"to":66}]},{"text":"Вместо «Я не ваш официант» — «Я вас слушаю», затем помогите или передайте просьбу ответственному сотруднику.","marks":[{"type":"bold","from":29,"to":43}]},{"text":"Вместо «У нас запара» — «Сейчас высокая загрузка» и конкретная информация об ожидании.","marks":[{"type":"bold","from":24,"to":49}]},{"text":"Вместо «Вам по готовности?» — повтор заказа по согласованным курсам.","marks":[{"type":"bold","from":30,"to":67}]}]'::jsonb,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-22_block_4','lesson-22',30,'heading','Обычная грамотная речь','[]'::jsonb,2,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-22_block_5','lesson-22',40,'paragraph','Говорим «Здравствуйте», «Добрый вечер», «Пожалуйста». Называем гостей «гость», «гостья», «гости». Используем слова «суп», «салат», «бокал», «заказ» без постоянных уменьшительных суффиксов.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-22_block_6','lesson-22',50,'paragraph','Не перечисляйте обрывками «Сироп? Сахар? Корица?». Сформулируйте полное предложение: «Какой сироп добавим в кофе?» — если гость уже выразил интерес к добавке.','[{"type":"italic","from":85,"to":114}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-22_block_7','lesson-22',60,'paragraph','Если кухня закрыта, объясните, что ещё действительно можно заказать. Не обещайте блюдо или десерт, не проверив доступность.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-22_block_8','lesson-22',70,'paragraph','Источник: «Запрещенные фразы», страницы 1–5.','[{"type":"italic","from":0,"to":44}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-23','Сервис','Разные гости: спокойное общение и помощь с выбором','Типы из учебного материала — ориентиры для общения, а не ярлыки. Один и тот же человек в разные дни ведёт себя по-разному. Смотрите на текущие потребности и слушайте слов…','published',230,false,'Разные гости: спокойное общение и помощь с выбором Сервис Типы из учебного материала — ориентиры для общения, а не ярлыки. Один и тот же человек в разные дни ведёт себя по-разному. Смотрите на текущие потребности и слушайте слов… Типы из учебного материала — ориентиры для общения, а не ярлыки. Один и тот же человек в разные дни ведёт себя по-разному. Смотрите на текущие потребности и слушайте слова гостя. Постоянный и лояльный гость Узнавайте гостя, по возможности обращайтесь по имени, помните предпочтения. При этом не считайте, что постоянный гость обязан терпеть ошибки. Он может промолчать, поэтому обратную связь лучше мягко уточнить. Спокойный гость Человек читает, работает или разговаривает негромко. Ему обычно подходит сдержанное обслуживание без суеты и лишних разговоров. Оставайтесь внимательны: спокойствие не означает, что помощь не нужна. Спокойный формат общения. Иллюстрация из «Типы гостей» Доброжелательный гость Он готов обсуждать решение и может стесняться высказать замечание. Поблагодарите за честный отзыв, уточните потребность и исправьте проблему. Вежливость гостя не делает замечание менее важным. Весёлый гость Поддержите лёгкий тон и уместную шутку, если это комфортно обеим сторонам. Следите, чтобы общение не мешало другим столам и не заменяло обслуживание. Неуверенный гость Предложите пару понятных вариантов, объясните различие и помогите выбрать. Не оставляйте человека с фразой «Решайте сами» и не принимайте решение без его согласия. Помощь с выбором. Иллюстрация из «Типы гостей» Источник: «Типы гостей», страницы 2–6. Формулировки адаптированы для уважительного общения.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
