insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-24','Сервис','Если гость требовательный, расстроенный или рассерженный','Сначала поймите, что случилось и какого решения ждёт гость. Не спорьте о характере человека и не обсуждайте его с коллегами в зале. Требовательный гость Ему важны конкрет…','published',240,false,'Если гость требовательный, расстроенный или рассерженный Сервис Сначала поймите, что случилось и какого решения ждёт гость. Не спорьте о характере человека и не обсуждайте его с коллегами в зале. Требовательный гость Ему важны конкрет… Сначала поймите, что случилось и какого решения ждёт гость. Не спорьте о характере человека и не обсуждайте его с коллегами в зале. Требовательный гость Ему важны конкретика, внимательность и сроки. Кратко подтвердите запрос, объясните возможное решение и держите слово. Если просьба выходит за ваши полномочия, подключите менеджера. Не обещайте невозможное ради быстрого согласия. Рассерженный гость Дайте высказаться без перебивания. Ответьте спокойным голосом, обозначьте проблему и предложите действие. Нарочитая улыбка, оправдания и попытка доказать, что «всё нормально», усиливают раздражение. Эмоциональное недовольство. Иллюстрация из «Типы гостей» Обиженный или расстроенный гость Проявите участие, уточните причину и предложите конкретное решение. Подарок сам по себе не исправляет проблему; любые комплименты и компенсации согласуйте по правилам заведения. Экспрессивный гость Он может много говорить и ярко проявлять эмоции. Поддерживайте доброжелательный контакт, но сохраняйте рабочие границы. Если общение мешает другим, спокойно напомните о правилах и при необходимости попросите помощи менеджера. Разочарованный гость Он может отказываться от предложений и хотеть уйти. Сделайте один внимательный шаг: признайте неприятный опыт, предложите выполнимый выход и уважайте решение гостя. Давление и длинные оправдания не возвращают доверие. Разочарование гостя. Иллюстрация из «Типы гостей» Источник: «Типы гостей», страницы 7–11. Рекомендации не отменяют рабочие правила и полномочия сотрудника.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
