insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-24_block_8','lesson-24',70,'paragraph','Проявите участие, уточните причину и предложите конкретное решение. Подарок сам по себе не исправляет проблему; любые комплименты и компенсации согласуйте по правилам заведения.','[]'::jsonb,null,null,null,null,null,'','','');
