insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-24_block_10','lesson-24',90,'paragraph','Он может много говорить и ярко проявлять эмоции. Поддерживайте доброжелательный контакт, но сохраняйте рабочие границы. Если общение мешает другим, спокойно напомните о правилах и при необходимости попросите помощи менеджера.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-24_block_11','lesson-24',100,'heading','Разочарованный гость','[]'::jsonb,2,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-24_block_12','lesson-24',110,'paragraph','Он может отказываться от предложений и хотеть уйти. Сделайте один внимательный шаг: признайте неприятный опыт, предложите выполнимый выход и уважайте решение гостя. Давление и длинные оправдания не возвращают доверие.','[]'::jsonb,null,null,null,null,null,'','','');
