insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-25','Сервис','Жалобы: техники LAST и LATTE','Цель — решить проблему и восстановить доверие. Готовая последовательность помогает не растеряться, но слова должны соответствовать ситуации. LAST 1. Listen — выслушай. Да…','published',250,false,'Жалобы: техники LAST и LATTE Сервис Цель — решить проблему и восстановить доверие. Готовая последовательность помогает не растеряться, но слова должны соответствовать ситуации. LAST 1. Listen — выслушай. Да… Цель — решить проблему и восстановить доверие. Готовая последовательность помогает не растеряться, но слова должны соответствовать ситуации. LAST Listen — выслушай. Дай гостю закончить, уточни непонятное. Apologize — извинись. Извиняйся от лица заведения, без поиска виноватого. Solve — реши. Предложи выполнимое решение или два понятных варианта. Thank — поблагодари. Покажи, что замечание услышали. «Жаль, что блюдо оказалось пересолено. Приношу извинения. Можем переделать его или подобрать другое — что вам удобнее? Спасибо, что сказали». LATTE Listen — выслушай. Acknowledge — признай переживание и проблему. Это не обязанность соглашаться с любым утверждением. Take action — предприми действие. Thank — поблагодари. Encourage — пригласи вернуться. Делай это после решения ситуации, без давления. «Понимаю, вы рассчитывали на менее острое блюдо. Давайте уточню возможность замены и предложу подходящий вариант. Спасибо за обратную связь». Когда нужен менеджер Подключайте менеджера, если решение выходит за ваши полномочия, гость не принимает доступные варианты или ситуация требует дополнительного разбора. При сообщении об инородном предмете сразу сообщите менеджеру, согласуйте замену и разбор ситуации. Не обещайте самовольно бесплатное блюдо или скидку. Извинение без действия не завершает работу с жалобой. После исправления вернитесь и убедитесь, что вопрос решён. Источник: презентация «LAST и LATTE», слайды 1–2. В исходной презентации нет встроенных фотографий или иллюстраций; алгоритмы переданы текстом.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
