insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-25_block_9','lesson-25',80,'paragraph','Подключайте менеджера, если решение выходит за ваши полномочия, гость не принимает доступные варианты или ситуация требует дополнительного разбора. При сообщении об инородном предмете сразу сообщите менеджеру, согласуйте замену и разбор ситуации. Не обещайте самовольно бесплатное блюдо или скидку.','[]'::jsonb,null,null,null,null,null,'','','');
