insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-26','Сервис','Поведение сотрудника в зале','Гость должен видеть внимательную, собранную команду. Рабочее общение ведём спокойно, без перекрикивания и демонстративной суеты. В поле зрения гостей - Не обсуждаем госте…','published',260,false,'Поведение сотрудника в зале Сервис Гость должен видеть внимательную, собранную команду. Рабочее общение ведём спокойно, без перекрикивания и демонстративной суеты. В поле зрения гостей - Не обсуждаем госте… Гость должен видеть внимательную, собранную команду. Рабочее общение ведём спокойно, без перекрикивания и демонстративной суеты. Иллюстрация из материала «Правила поведения в зале» В поле зрения гостей Не обсуждаем гостей и не используем пренебрежительные обращения. Не разговариваем громко, не кричим через зал. Не собираемся группой для личной беседы; по стандарту — не более двух сотрудников в одном месте без рабочей необходимости. Не облокачиваемся на поверхности и не стоим спиной к залу. Не поправляем волосы и одежду, не касаемся лица на глазах у гостей. Не едим, не пьём и не пользуемся личным телефоном в зале. Не обнимаемся с коллегами и не устраиваем демонстративные приветствия вроде «дай пять». Личные дела и приведение себя в порядок перенесите в предназначенную для этого зону. По стандарту для сотрудников зала вход за барную стойку ограничен; рабочие действия бармена в его зоне это правило не запрещает. Если нужна помощь коллеги, обратитесь спокойно и передайте конкретную просьбу. Продолжайте следить за своим участком и сигналами гостей. Источник: «Правила поведения в зале», страницы 1–2. Уточнение о барной зоне добавлено, чтобы правило для сотрудников зала не трактовалось как запрет работы бармена.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
