insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-26_block_4','lesson-26',30,'list',null,'[]'::jsonb,null,false,'[{"text":"Не обсуждаем гостей и не используем пренебрежительные обращения.","marks":[]},{"text":"Не разговариваем громко, не кричим через зал.","marks":[]},{"text":"Не собираемся группой для личной беседы; по стандарту — не более двух сотрудников в одном месте без рабочей необходимости.","marks":[]},{"text":"Не облокачиваемся на поверхности и не стоим спиной к залу.","marks":[]},{"text":"Не поправляем волосы и одежду, не касаемся лица на глазах у гостей.","marks":[]},{"text":"Не едим, не пьём и не пользуемся личным телефоном в зале.","marks":[]},{"text":"Не обнимаемся с коллегами и не устраиваем демонстративные приветствия вроде «дай пять».","marks":[]}]'::jsonb,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-26_block_5','lesson-26',40,'paragraph','Личные дела и приведение себя в порядок перенесите в предназначенную для этого зону. По стандарту для сотрудников зала вход за барную стойку ограничен; рабочие действия бармена в его зоне это правило не запрещает.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-26_block_6','lesson-26',50,'paragraph','Если нужна помощь коллеги, обратитесь спокойно и передайте конкретную просьбу. Продолжайте следить за своим участком и сигналами гостей.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-26_block_7','lesson-26',60,'paragraph','Источник: «Правила поведения в зале», страницы 1–2. Уточнение о барной зоне добавлено, чтобы правило для сотрудников зала не трактовалось как запрет работы бармена.','[{"type":"italic","from":0,"to":164}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_articles(id,category,title,description,status,sort_order,dashboard_featured,search_text,revision,created_by,updated_by,created_at,updated_at,published_at) values ('lesson-27','Вино','Как объяснить вино простыми словами','Начните с понятных ориентиров: тихое или игристое, цвет, сладость, кислотность, терпкость и несколько заметных ароматов. Не обязательно перечислять весь дегустационный сл…','published',270,false,'Как объяснить вино простыми словами Вино Начните с понятных ориентиров: тихое или игристое, цвет, сладость, кислотность, терпкость и несколько заметных ароматов. Не обязательно перечислять весь дегустационный сл… Начните с понятных ориентиров: тихое или игристое, цвет, сладость, кислотность, терпкость и несколько заметных ароматов. Не обязательно перечислять весь дегустационный словарь. Сладость, аромат и ощущения Тихое вино не обладает выраженной игристостью. Фруктовые ноты не означают, что в вино добавили фрукты или что оно сладкое: сухое вино тоже может напоминать ягоды, яблоко или грушу. Кислотность даёт освежающее ощущение. Танины ощущаются как терпкость, лёгкая сухость и стягивание во рту. Цвет сам по себе не говорит о сладости: розовое вино бывает сухим. Если гость просит «мягкое», уточните, что он имеет в виду: меньше кислотности, меньше терпкости или больше сладости. Купаж — сочетание вин или сортов винограда в одном вине. Игристые без путаницы Champagne — из французской Шампани; второе брожение проходит в бутылке. Просекко — основа Глера. Не нужно говорить, что любое Просекко обязательно состоит только из одного сорта. Кава — испанское игристое традиционного метода со вторым брожением в бутылке. Французский Креман — игристое классического метода из регионов вне Шампани. Асти в нашей учебной карте — сладкое ароматное игристое из Москато. Пет-нат разливают до завершения первичного брожения, которое продолжается в бутылке. В обозначениях игристого Extra Dry слаще Brut, несмотря на буквальный перевод названия. Оранжевое и безалкогольное Оранжевое вино получают из белого винограда с контактом с кожицей. Апельсины для этого не нужны. Такой способ сам по себе не гарантирует органический статус или отсутствие фильтрации. Безалкогольное вино выбирайте по маркировке конкретной бутылки. Не обещайте полное отсутствие алкоголя, если это не подтверждает этикетка. Работа с вашей картой У каждой позиции есть конкретное название, производитель и винтаж. Если этикетка отличается от старых заметок, сначала уточните актуальные данные. Не переносите состав одного вина на все вина бренда. Дополнительные источники: Comité Champagne — второе брожение и сорта винограда; Consorzio Prosecco DOC — правила производства; D.O. Cava — традиционный метод. Точные ссылки находятся в SOURCES_AND_REVIEW.txt в архиве обновления.',1,null,null,clock_timestamp(),clock_timestamp(),clock_timestamp());
