insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_4','lesson-27',30,'paragraph','Кислотность даёт освежающее ощущение. Танины ощущаются как терпкость, лёгкая сухость и стягивание во рту. Цвет сам по себе не говорит о сладости: розовое вино бывает сухим.','[{"type":"bold","from":0,"to":11},{"type":"bold","from":38,"to":44}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_5','lesson-27',40,'paragraph','Если гость просит «мягкое», уточните, что он имеет в виду: меньше кислотности, меньше терпкости или больше сладости. Купаж — сочетание вин или сортов винограда в одном вине.','[{"type":"bold","from":117,"to":122}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_6','lesson-27',50,'heading','Игристые без путаницы','[]'::jsonb,2,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_7','lesson-27',60,'list',null,'[]'::jsonb,null,false,'[{"text":"Champagne — из французской Шампани; второе брожение проходит в бутылке.","marks":[{"type":"bold","from":0,"to":9}]},{"text":"Просекко — основа Глера. Не нужно говорить, что любое Просекко обязательно состоит только из одного сорта.","marks":[{"type":"bold","from":0,"to":8}]},{"text":"Кава — испанское игристое традиционного метода со вторым брожением в бутылке.","marks":[{"type":"bold","from":0,"to":4}]},{"text":"Французский Креман — игристое классического метода из регионов вне Шампани.","marks":[{"type":"bold","from":0,"to":18}]},{"text":"Асти в нашей учебной карте — сладкое ароматное игристое из Москато.","marks":[{"type":"bold","from":0,"to":4}]},{"text":"Пет-нат разливают до завершения первичного брожения, которое продолжается в бутылке.","marks":[{"type":"bold","from":0,"to":7}]}]'::jsonb,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_8','lesson-27',70,'quote','В обозначениях игристого Extra Dry слаще Brut, несмотря на буквальный перевод названия.','[{"type":"bold","from":25,"to":45}]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_9','lesson-27',80,'heading','Оранжевое и безалкогольное','[]'::jsonb,2,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_10','lesson-27',90,'paragraph','Оранжевое вино получают из белого винограда с контактом с кожицей. Апельсины для этого не нужны. Такой способ сам по себе не гарантирует органический статус или отсутствие фильтрации.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_11','lesson-27',100,'paragraph','Безалкогольное вино выбирайте по маркировке конкретной бутылки. Не обещайте полное отсутствие алкоголя, если это не подтверждает этикетка.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_12','lesson-27',110,'heading','Работа с вашей картой','[]'::jsonb,2,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_13','lesson-27',120,'paragraph','У каждой позиции есть конкретное название, производитель и винтаж. Если этикетка отличается от старых заметок, сначала уточните актуальные данные. Не переносите состав одного вина на все вина бренда.','[]'::jsonb,null,null,null,null,null,'','','');
insert into public.knowledge_article_blocks(id,article_id,sort_order,block_type,text_content,marks,heading_level,list_ordered,list_items,media_id,legacy_src,alt_text,caption,media_name) values ('lesson-27_block_14','lesson-27',130,'paragraph','Дополнительные источники: Comité Champagne — второе брожение и сорта винограда; Consorzio Prosecco DOC — правила производства; D.O. Cava — традиционный метод. Точные ссылки находятся в SOURCES_AND_REVIEW.txt в архиве обновления.','[{"type":"italic","from":0,"to":228}]'::jsonb,null,null,null,null,null,'','','');
